import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { createHighlighter } from "shiki";
import { createRequire } from "node:module";
import { parseFragment } from "parse5";
import { sanitizeShikiHtml, ShikiSanitizationError } from "../src/shikiSanitizer.js";

// Producer fixtures are generated by EXACT Shiki 4.5.0, never hand-labelled as Shiki output.
const PRODUCER_VERSION = "4.5.0";
const rootStyle = "--shiki-light:#123;--shiki-dark:#abcdef;--shiki-light-bg:#fff;--shiki-dark-bg:#000";
const wrap = (content: string, style = rootStyle) => `<pre class="shiki shiki-themes github-light github-dark" style="${style}" tabindex="0"><code>${content}</code></pre>`;
const line = (content = "") => `<span class="line">${content}</span>`;
const token = (text = "", style?: string) => `<span${style === undefined ? "" : ` style="${style}"`}>${text}</span>`;
const plain = (text = "") => wrap(line(token(text)));
function textContent(html: string): string {
  const walk = (node: ReturnType<typeof parseFragment>["childNodes"][number]): string => "value" in node ? node.value : "childNodes" in node ? node.childNodes.map(walk).join("") : "";
  return parseFragment(html).childNodes.map(walk).join("");
}
function refused(input: string, code?: ShikiSanitizationError["code"]) {
  let output: string | undefined;
  try { output = sanitizeShikiHtml(input); } catch (error) {
    expect(error).toBeInstanceOf(ShikiSanitizationError);
    if (code) expect((error as ShikiSanitizationError).code).toBe(code);
    expect(output).toBeUndefined();
    return;
  }
  throw new Error("Expected refusal");
}

describe("Shiki 4.5 classic dual-theme profile", () => {
  let highlighter: Awaited<ReturnType<typeof createHighlighter>>;
  beforeAll(async () => {
    const require = createRequire(import.meta.url);
    expect(require("shiki/package.json").version).toBe(PRODUCER_VERSION);
    highlighter = await createHighlighter({ themes: ["github-light", "github-dark"], langs: ["typescript", "html", "css", "json", "markdown", "diff"] });
  }, 30_000);
  afterAll(() => highlighter?.dispose());
  const fixtures = [
    ["text", ""], ["text", "plain"], ["text", "\n"], ["text", "a\n\n"],
    ["typescript", 'const x = "<& 😀 café";\n// comment'],
    ["html", '<script src="https://invalid.example/x">alert(1)</script>'],
    ["css", '.x { color: #ab12; background: url("https://invalid.example"); }'],
    ["json", '{"key": "&lt; &#x3c; < > &"}'],
    ["markdown", "# Title\n**bold** *italic* ~~strike~~ [link](https://invalid.example)"],
    ["diff", "- old\n+ new"],
    ["ansi", "\u001b[2mdim alpha\u001b[0m"],
    ["ansi", "\u001b[3mitalic\u001b[0m \u001b[1mbold\u001b[0m"],
  ];
  for (const [lang, source] of fixtures) it(`accepts real ${lang} fixture ${JSON.stringify(source)}`, () => {
    const html = highlighter.codeToHtml(source, { lang, themes: { light: "github-light", dark: "github-dark" }, defaultColor: false });
    const out = sanitizeShikiHtml(html);
    expect(textContent(out)).toBe(lang === "ansi" ? source.replace(/\u001b\[[0-9;]*m/g, "") : source);
    expect(out).toContain('class="rk-shiki-profile shiki shiki-themes"');
    expect(out).not.toContain("github-light");
  });
  it("accepts actual paired font output from real Markdown themes", () => {
    const html = highlighter.codeToHtml("**bold** *italic* ~~strike~~", { lang: "markdown", themes: { light: "github-light", dark: "github-dark" }, defaultColor: false });
    expect(html).toMatch(/--shiki-light-(font-weight|font-style|text-decoration):/);
    expect(textContent(sanitizeShikiHtml(html))).toBe("**bold** *italic* ~~strike~~");
  });
  it("refuses real ANSI token backgrounds for explicit source fallback", () => {
    const html = highlighter.codeToHtml("\u001b[41mred background\u001b[0m", { lang: "ansi", themes: { light: "github-light", dark: "github-dark" }, defaultColor: false });
    expect(html).toMatch(/<span style="[^"]*--shiki-light-bg:/);
    refused(html, "style");
  });
  it("accepts entities, empty tokens, uppercase hex & alpha colors", () => {
    for (const color of ["#ABC", "#ABCD", "#aBcDeF", "#aBcDeF12"]) {
      const html = wrap(line(token("&lt;img&gt;&amp;&#39;😀", `--shiki-light:${color};--shiki-dark:${color}`) + token()));
      expect(textContent(sanitizeShikiHtml(html))).toBe("<img>&'😀");
    }
  });
  it("accepts paired finite font values & refuses font-only/unsupported producer shapes", () => {
    for (const [kind, value] of [["font-style", "italic"], ["font-weight", "bold"], ["text-decoration", "underline"], ["text-decoration", "line-through"], ["text-decoration", "underline line-through"]]) {
      const fonts = `--shiki-light-${kind}:${value};--shiki-dark-${kind}:inherit`;
      expect(sanitizeShikiHtml(wrap(line(token("x", `--shiki-light:#123;--shiki-dark:#456;${fonts}`))))).toContain(fonts);
      refused(wrap(line(token("x", fonts))), "style");
    }
    refused(highlighter.codeToHtml("x", { lang: "text", theme: "github-light" }));
  });
  it("rejects markup, foreign namespaces, comments, extra attrs & parser repairs", () => {
    for (const child of ['<script>alert(1)</script>', '<img src="https://invalid.example" onerror="alert(1)">', '<svg><a href="x"></a></svg>', '<math></math>', '<!--x-->', '<br>', '<span onclick="alert(1)">x</span>', '<span class="token">x</span>', '<span><b>x</b></span>', '<span>x', 'raw text']) refused(wrap(line(child)));
    for (const html of [plain().replace("<code>", '<code id="x">'), plain().replace("tabindex=\"0\"", 'tabindex="1"'), plain().replace("<pre ", '<pre style="x" '), plain().replace("</span></span>", "</span>"), plain() + '<!--x-->']) refused(html);
  });
  it("rejects ignored source intervals & raw less-than text; accepts encoded less-than", () => {
    for (const html of [plain("a<b"), plain().replace("<code>", "\n<code>"), plain().replace("<code>", "<code></bogus>"), plain().replace("</code>", "</code></bogus>"), plain().replace("<code>", "<code><html>"), plain().replace("<pre ", "<!doctype html><pre ")]) refused(html);
    expect(textContent(sanitizeShikiHtml(plain("a&lt;b")))).toBe("a<b");
  });
  it("requires exact LF siblings & one code child", () => {
    expect(textContent(sanitizeShikiHtml(wrap(line() + "\n" + line())))).toBe("\n");
    for (const gap of [" ", "\r\n", "&#10;", "\n\n", "<!--x-->"]) refused(wrap(line() + gap + line()));
    refused(wrap(line() + "\n"));
    refused(wrap(""));
    refused(plain().replace("</code>", "</code><code></code>"));
  });
  it("refuses nonfinite CSS & noncanonical declarations", () => {
    for (const style of ["color:red", "--shiki-light:red;--shiki-dark:#123", "--shiki-light:#123;--shiki-dark:#456;", "--shiki-light: #123;--shiki-dark:#456", "--shiki-light:#123;--shiki-dark:#456;--shiki-light:#fff", "--shiki-light:var(--x);--shiki-dark:#123", "--shiki-light:#123;--shiki-dark:#456;--shiki-light-bg:#fff", "--shiki-light:#123;--shiki-dark:#456;--shiki-light-font-style:italic", "--shiki-light:#123;--shiki-dark:#456;--shiki-light-font-style:inherit;--shiki-dark-font-style:inherit", "--shiki-light:#123/*x*/;--shiki-dark:#456", "--shiki-light:\\23fff;--shiki-dark:#456", "--shiki-light:url(https://invalid.example);--shiki-dark:#123"]) refused(wrap(line(token("x", style))), "style");
  });
  it("bounds tokenizer attribute work before parse5, including quoted tag boundaries", () => {
    const manyAttrs = Array.from({ length: 100_000 }, (_, i) => ` a${i}="x"`).join("");
    refused(`<pre${manyAttrs}></pre>`, "structure");
    refused(`<pre class="quoted > data"${manyAttrs}></pre>`, "structure");
    refused(plain().replace('class="shiki', 'class="nested < shiki'), "syntax");
    refused(plain().replace('class="shiki', "class='shiki"), "syntax");
    refused('<pre class="unclosed > value', "syntax");
    refused(plain().replace('<code>', '<code/>'), "syntax");
    refused(plain().replace('<code>', '<code class="x">'), "structure");
    refused(plain().replace('<span class="line">', '<span class="line" style="x">'), "structure");
    // Whitespace pads a valid tag to exact raw UTF-16 boundary without changing semantics.
    const originalTag = plain().slice(0, plain().indexOf(">") + 1);
    const atBoundary = originalTag.slice(0, -1) + " ".repeat(2048 - originalTag.length) + ">";
    expect(sanitizeShikiHtml(plain().replace(originalTag, atBoundary))).toContain("rk-shiki-profile");
    refused(plain().replace(originalTag, atBoundary.slice(0, -1) + " >"), "limit");
    // Real Shiki fixtures above also traverse this guard with entity text & exact LF intact.
    expect(textContent(sanitizeShikiHtml(plain("&lt;x&gt; &amp;")))).toBe("<x> &");
  });
  it("enforces input/output byte, line, depth, class, style & allocation ceilings", () => {
    refused("x".repeat(4_194_305), "limit");
    refused("😀".repeat(1_048_577), "limit");
    const room = 4_194_304 - sanitizeShikiHtml(plain("")).length;
    const atOutputLimit = "'".repeat(Math.floor(room / 5)) + "x".repeat(room % 5);
    expect(sanitizeShikiHtml(plain(atOutputLimit))).toHaveLength(4_194_304);
    refused(plain(atOutputLimit + "x"), "limit");
    refused(plain("'".repeat(850_000)), "limit");
    expect(sanitizeShikiHtml(wrap(Array(16_384).fill(line()).join("\n")))).toContain("</pre>");
    refused(wrap(Array(16_385).fill(line()).join("\n")), "limit");
    // parse5 allocates template context, documentmock, html scaffold & fragment: four nodes.
    expect(sanitizeShikiHtml(wrap(line(token().repeat(65_529))))).toContain("</pre>");
    refused(wrap(line(token().repeat(65_530))), "limit");
    refused(wrap(line("<span>".repeat(10) + "</span>".repeat(10))), "limit");
    refused(plain().replace("github-light github-dark", "x".repeat(513)), "limit");
    expect(sanitizeShikiHtml(plain().replace("github-light github-dark", "x".repeat(512 - "shiki shiki-themes ".length)))).toContain("rk-shiki-profile");
    refused(wrap(line(token("x", "x".repeat(513)))), "limit");
  }, 30_000);
});
